import type { ResumeKind } from "@/lib/resume/constants";
import type { ParsedResume, ResumeHealth } from "@/lib/resume/schemas";

export interface ResumeSummary {
  id: string;
  file_name: string;
  kind: ResumeKind;
  size_bytes: number;
  page_count: number;
  health_score: number;
  created_at: string;
}

export interface ResumeRecord extends ResumeSummary {
  sha256: string;
  extracted_text: string;
  parsed: ParsedResume;
  health: ResumeHealth;
  /** False in demo mode, where the original file is never kept. */
  has_file: boolean;
}

export interface NewResume {
  /** Generated by the app so the storage path can be built before the row exists. */
  id: string;
  file_name: string;
  kind: ResumeKind;
  size_bytes: number;
  sha256: string;
  page_count: number;
  extracted_text: string;
  parsed: ParsedResume;
  health: ResumeHealth;
}

export type ResumeStoreErrorKind = "duplicate" | "unknown";

export class ResumeStoreError extends Error {
  constructor(
    public readonly kind: ResumeStoreErrorKind,
    cause?: unknown,
  ) {
    super(`Resume store error: ${kind}`, cause === undefined ? undefined : { cause });
    this.name = "ResumeStoreError";
  }
}

export interface ResumeStore {
  list(userId: string): Promise<ResumeSummary[]>;
  get(userId: string, id: string): Promise<ResumeRecord | null>;
  findByHash(userId: string, sha256: string): Promise<ResumeSummary | null>;
  count(userId: string): Promise<number>;
  /** Persists the row and, where the store keeps files, the original bytes. */
  create(userId: string, record: NewResume, file: Uint8Array): Promise<ResumeSummary>;
  /** Removes the file and the row. Returns false when the resume does not exist. */
  delete(userId: string, id: string): Promise<boolean>;
  /** A short-lived download link, or null when no original file is kept. */
  signedUrl(userId: string, id: string): Promise<string | null>;
}
